#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/git-pull.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Bring the core branches up to date from origin, here and in each member"
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="also each other branch of origin, not only the core branches and the default branch"

# The task fetches origin in this repository and in each submodule and sibling
# member that is on this machine. Then, for each branch of the set, it:
#
#   - creates a local branch that tracks origin/<branch>, when none exists;
#   - fast-forwards the local branch when origin is ahead;
#   - keeps the local branch when it has commits that origin does not have,
#     also when the two branches diverge (a warning names it).
#
# The set is core_branches and default_branch of `.config/bootstrap/repo.toml`,
# or main and develop in a member without `.config/bootstrap/`. With --all, it
# is each branch of origin. The task never merges, rebases or deletes a branch.
# A branch that a worktree has checked out moves with `git merge --ff-only` in
# that worktree, so its files move too; each other branch moves with
# `git update-ref`.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

ALL = os.environ.get("usage_all") == "true"


def git(folder, *args):
  """Runs git in folder. Returns (code, stdout without the last line break)."""
  result = subprocess.run(
    ["git", "-C", folder, *args], check=False, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True
  )
  return result.returncode, result.stdout.rstrip("\n")


def checked_out(folder):
  """A map from each branch that a worktree has checked out to its folder."""
  _, out = git(folder, "worktree", "list", "--porcelain")
  result = {}
  path = ""
  for line in out.split("\n"):
    if line.startswith("worktree "):
      path = line.removeprefix("worktree ")
    elif line.startswith("branch refs/heads/"):
      result[line.removeprefix("branch refs/heads/")] = path
  return result


def branch_set(folder, root):
  """The branches to bring up to date in the repository of folder."""
  if ALL:
    _, out = git(folder, "for-each-ref", "--format=%(refname:lstrip=3)", "refs/remotes/origin/")
    return [b for b in out.split("\n") if b and b != "HEAD"]
  if not os.path.isdir(f"{folder}/.config/bootstrap"):
    return ["main", "develop"]
  repo = None if folder == root else folder
  names = [str(b) for b in helpers.core_branches(repo)]
  default = helpers.default_branch(repo)
  if default not in names:
    names.append(default)
  return names


def pull_branch(folder, branch, worktrees):
  """Brings one local branch up to date with origin/<branch>. Returns False on
  a failure."""
  remote = f"refs/remotes/origin/{branch}"
  code, theirs = git(folder, "rev-parse", "--verify", "--quiet", remote)
  if code != 0:
    helpers.print_info(f"{branch}: not on origin")
    return True
  code, ours = git(folder, "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}")
  if code != 0:
    if git(folder, "branch", "--quiet", "--track", branch, f"origin/{branch}")[0] != 0:
      helpers.print_error(f"{branch}: FAILED to create the local branch")
      return False
    helpers.print_success(f"{branch}: created from origin/{branch}")
    return True
  if ours == theirs:
    helpers.print_info(f"{branch}: up to date")
    return True
  if git(folder, "merge-base", "--is-ancestor", theirs, ours)[0] == 0:
    helpers.print_info(f"{branch}: ahead of origin, kept")
    return True
  if git(folder, "merge-base", "--is-ancestor", ours, theirs)[0] != 0:
    helpers.print_warn(f"{branch}: has diverged from origin, kept - merge or rebase it by hand")
    return True
  if branch in worktrees:
    code = subprocess.run(
      ["git", "-C", worktrees[branch], "merge", "--quiet", "--ff-only", theirs], check=False
    ).returncode
    if code != 0:
      helpers.print_error(f"{branch}: FAILED to fast-forward in {worktrees[branch]}")
      return False
  elif git(folder, "update-ref", f"refs/heads/{branch}", theirs, ours)[0] != 0:
    helpers.print_error(f"{branch}: FAILED to fast-forward")
    return False
  _, count = git(folder, "rev-list", "--count", f"{ours}..{theirs}")
  helpers.print_success(f"{branch}: fast-forwarded {count} commit(s)")
  return True


def pull_repo(folder, root):
  """Fetches origin in the repository of folder, then brings each branch of the
  set up to date. Returns False on a failure."""
  if git(folder, "remote", "get-url", "origin")[0] != 0:
    helpers.print_info("No origin remote, nothing to pull")
    return True
  helpers.print_wait("Fetching origin ... ")
  if git(folder, "fetch", "--quiet", "--prune", "--tags", "origin")[0] != 0:
    helpers.print_error()
    helpers.print_error("FAILED to fetch origin!")
    return False
  helpers.print_success()
  worktrees = checked_out(folder)
  ok = True
  for branch in branch_set(folder, root):
    ok = pull_branch(folder, branch, worktrees) and ok
  return ok


root = os.environ["MISE_PROJECT_ROOT"]
helpers.print_header("Pulling the branches from origin ...")
ok = pull_repo(root, root)

# Each member is a separate repository. A member that is not on this machine is
# skipped with a warning, as setup:configs does.
for name, folder, label, _ in helpers.members():
  helpers.print_header(f"Pulling {label} ...")
  path = os.path.normpath(f"{root}/{folder}")
  if git(path, "rev-parse", "--git-dir")[0] != 0:
    helpers.print_warn(f"member {name}: {folder} is not on this machine")
    continue
  ok = pull_repo(path, root) and ok

sys.exit(0 if ok else 1)
